 "content": "def transform(grid):
    """Extend 2-markers down their lattice columns and 3-markers across rows."""
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def spans(length, separators):
        bounds = [-1] + separators + [length]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    out = [row[:] for row in grid]
    horizontal = set()
    vertical = set()

    for pr, (r0, r1) in enumerate(row_spans):
        for pc, (c0, c1) in enumerate(col_spans):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] == 2:
                        vertical.add(pc)
                    elif grid[r][c] == 3:
                        horizontal.add(pr)

    for pr, (r0, r1) in enumerate(row_spans):
        for pc, (c0, c1) in enumerate(col_spans):
            color = 6 if pr in horizontal and pc in vertical else (
                3 if pr in horizontal else 2 if pc in vertical else 0
            )
            if color:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = color
    return out

